import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"采芑","description":"","frontmatter":{"title":"采芑","date":"2026-11-08T00:00:00.000Z","seq":18,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/采芑.md","filePath":"blogs/诗经·小雅/采芑.md"}'),p={name:"blogs/诗经·小雅/采芑.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="采芑" tabindex="-1">采芑 <a class="header-anchor" href="#采芑" aria-label="Permalink to &quot;采芑&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　南有嘉鱼之什</p><div class="poem"><p class="poem-stanza">薄言采芑，于彼新田，呈此菑亩。方叔涖止，其车三千。师干之试，方叔率止。</p><p class="poem-stanza">乘其四骐，四骐翼翼。路车有奭，簟茀鱼服，钩膺鞗革。</p><p class="poem-stanza">薄言采芑，于彼新田，于此中乡。方叔涖止，其车三千。旂旐央央，方叔率止。</p><p class="poem-stanza">约軧错衡，八鸾玱玱。服其命服，朱芾斯皇，有玱葱珩。</p><p class="poem-stanza">鴥彼飞隼，其飞戾天，亦集爰止。方叔涖止，其车三千。师干之试，方叔率止。</p><p class="poem-stanza">钲人伐鼓，陈师鞠旅。显允方叔，伐鼓渊渊，振旅阗阗。</p><p class="poem-stanza">蠢尔蛮荆，大邦为仇。方叔元老，克壮其犹。方叔率止，执讯获丑。戎车啴啴，</p><p class="poem-stanza">啴啴焞焞，如霆如雷。显允方叔，征伐玁狁，蛮荆来威。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
